#!/bin/bash
set -euo pipefail
# Both settings files are generated by install.sh and owned by root.
source /etc/outline-interconnect.env
exec 9>/run/outline-interconnect.lock
flock 9
# Only replace our own table. nft commits the removal and new rules atomically.
rules=/etc/outline-interconnect.nft
stamp=/run/outline-interconnect-guard.sha256
table_exists=false
current=''
if current=$(nft -s list table inet olpath_guard 2>/dev/null); then
    table_exists=true
fi
signature() {
    { cat "$rules"; printf '%s' "$1"; } | sha256sum
}
if [[ $table_exists == false || ! -f $stamp || $(signature "$current") != "$(< "$stamp")" ]]; then
    {
        if [[ $table_exists == true ]]; then echo 'delete table inet olpath_guard'; fi
        cat "$rules"
    } | nft -f -
    current=$(nft -s list table inet olpath_guard)
    signature "$current" >"$stamp"
fi
if ! ip link show olpath0 >/dev/null 2>&1; then
    ip tunnel add olpath0 mode ipip local "$OUTER_LOCAL" remote "$OUTER_REMOTE" ttl 64
else
    tunnel=$(ip tunnel show olpath0)
    if [[ "$tunnel" != *"remote $OUTER_REMOTE local $OUTER_LOCAL "* ]]; then
        ip tunnel change olpath0 mode ipip local "$OUTER_LOCAL" remote "$OUTER_REMOTE" ttl 64
    fi
fi
if ! ip -o -4 addr show dev olpath0 | grep -Fq "inet $INNER_LOCAL/30 "; then
    ip address replace "$INNER_LOCAL/30" dev olpath0
fi
if [[ $(< /sys/class/net/olpath0/mtu) != 1380 ]] || (( !( $(< /sys/class/net/olpath0/flags) & 1 ) )); then
    ip link set olpath0 mtu 1380 up
fi
